                const int64_t grad_cart_ind_T = grad_cart_ind_1 * 3 + grad_cart_ind_0;

                gpu::computeCoulombHessianDDSP_IK_0<<<dd_num_blocks, dd_threads_per_block, 0, stream>>>(
