    exchange_timer.start();

    timer.start("K computation");

    // set up primitive Cartesian AO to atom mapping

    for (int64_t i = 0; i < s_prim_count; i++)
    {
        const auto i_cgto = s_prim_aoinds[i];

        prim_cart_ao_to_atom_inds[i] = cart_ao_to_atom_inds[i_cgto];
    }

    for (int64_t i = 0; i < p_prim_count * 3; i++)
    {
        const auto i_cgto = p_prim_aoinds[(i / 3) + p_prim_count * (i % 3)];

        prim_cart_ao_to_atom_inds[s_prim_count + i] = cart_ao_to_atom_inds[i_cgto];
    }

    for (int64_t i = 0; i < d_prim_count * 6; i++)
    {
        const auto i_cgto = d_prim_aoinds[(i / 6) + d_prim_count * (i % 6)];

        prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + i] = cart_ao_to_atom_inds[i_cgto];
    }

    gpuSafe(gpuMemcpyAsync(d_prim_cart_ao_to_atom_inds, prim_cart_ao_to_atom_inds.data(), all_prim_count * sizeof(uint32_t), gpuMemcpyHostToDevice, stream));

    // compute K

    for (int64_t exch_idx = 0; exch_idx < static_cast<int64_t>(frac_exact_exchange_values.size()); exch_idx++)
    {
    const auto frac_exact_exchange = frac_exact_exchange_values[exch_idx];
    const auto omega = omega_values[exch_idx];

    if (std::fabs(frac_exact_exchange) > 1.0e-13)
    {

    // K: S-S block

    if (pair_inds_count_for_K_ss > 0)
    {
        timer.start("  K block SS");

        // set up thread blocks for K

        dim3 threads_per_block(TILE_DIM_X_K, TILE_DIM_Y_K);

        dim3 num_blocks(pair_inds_count_for_K_ss, 1);

        // K: (SS|SS)
        //     *  *

        screening.update_j_or_l_vectors(static_cast<uint32_t>(natoms),
                                        pair_displs_K_ss,
                                        pair_counts_K_ss,
                                        D_inds_K_ss,
                                        static_cast<uint32_t>(s_prim_count),
                                        std::string("s"),
                                        s_prim_aoinds,
                                        cart_ao_to_atom_inds,
                                        atom_ids_j,
                                        atom_ids_j_displs,
                                        atom_ids_j_counts);

        screening.update_j_or_l_vectors(static_cast<uint32_t>(natoms),
                                        pair_displs_K_ss,
                                        pair_counts_K_ss,
                                        D_inds_K_ss,
                                        static_cast<uint32_t>(s_prim_count),
                                        std::string("s"),
                                        s_prim_aoinds,
                                        cart_ao_to_atom_inds,
                                        atom_ids_l,
                                        atom_ids_l_displs,
                                        atom_ids_l_counts);

        gpuSafe(gpuMemcpyAsync(d_atom_ids_j,        atom_ids_j.data(),        atom_ids_j.size()        * sizeof(uint32_t), gpuMemcpyHostToDevice, stream));
        gpuSafe(gpuMemcpyAsync(d_atom_ids_j_displs, atom_ids_j_displs.data(), atom_ids_j_displs.size() * sizeof(uint32_t), gpuMemcpyHostToDevice, stream));
        gpuSafe(gpuMemcpyAsync(d_atom_ids_j_counts, atom_ids_j_counts.data(), atom_ids_j_counts.size() * sizeof(uint32_t), gpuMemcpyHostToDevice, stream));

        gpuSafe(gpuMemcpyAsync(d_atom_ids_l,        atom_ids_l.data(),        atom_ids_l.size()        * sizeof(uint32_t), gpuMemcpyHostToDevice, stream));
        gpuSafe(gpuMemcpyAsync(d_atom_ids_l_displs, atom_ids_l_displs.data(), atom_ids_l_displs.size() * sizeof(uint32_t), gpuMemcpyHostToDevice, stream));
        gpuSafe(gpuMemcpyAsync(d_atom_ids_l_counts, atom_ids_l_counts.data(), atom_ids_l_counts.size() * sizeof(uint32_t), gpuMemcpyHostToDevice, stream));

        for (int64_t grad_cart_ind_0 = 0; grad_cart_ind_0 < 3; grad_cart_ind_0++)
        for (int64_t grad_cart_ind_1 = 0; grad_cart_ind_1 < 3; grad_cart_ind_1++)
        {
            const int64_t grad_cart_ind   = grad_cart_ind_0 * 3 + grad_cart_ind_1;
            const int64_t grad_cart_ind_T = grad_cart_ind_1 * 3 + grad_cart_ind_0;

            // we make use of IK<->JL symmetry for ground state Hessian

            gpu::computeExchangeHessianSSSS_IK_0<<<num_blocks, threads_per_block, 0, stream>>>(
                               d_hess_array[grad_cart_ind],
                               d_hess_array[grad_cart_ind_T],
                               static_cast<uint32_t>(grad_cart_ind_0),
                               static_cast<uint32_t>(grad_cart_ind_1),
                               frac_exact_exchange,
                               d_pair_inds_i_for_K_ss,
                               d_pair_inds_k_for_K_ss,
                               d_D_ik_for_K_ss,
                               static_cast<uint32_t>(pair_inds_count_for_K_ss),
                               d_s_prim_info,
                               d_s_prim_aoinds,
                               static_cast<uint32_t>(s_prim_count),
                               ss_max_D,
                               d_mat_D_full_AO,
                               static_cast<uint32_t>(cart_naos),
                               d_Q_K_ss,
                               d_D_inds_K_ss,
                               d_pair_displs_K_ss,
                               d_pair_counts_K_ss,
                               d_pair_data_K_ss,
                               d_prim_cart_ao_to_atom_inds,
                               static_cast<uint32_t>(natoms),
                               d_boys_func_table,
                               d_boys_func_ft,
                               omega,
                               eri_threshold);
            gpu::computeExchangeHessianSSSS_IL_0<<<num_blocks, threads_per_block, 0, stream>>>(
                               d_hess_array[grad_cart_ind],
                               d_hess_array[grad_cart_ind_T],
                               static_cast<uint32_t>(grad_cart_ind_0),
                               static_cast<uint32_t>(grad_cart_ind_1),
                               frac_exact_exchange,
                               d_pair_inds_i_for_K_ss,
                               d_pair_inds_k_for_K_ss,
                               d_D_ik_for_K_ss,
                               static_cast<uint32_t>(pair_inds_count_for_K_ss),
                               d_s_prim_info,
                               d_s_prim_aoinds,
                               static_cast<uint32_t>(s_prim_count),
                               ss_max_D,
                               d_mat_D_full_AO,
                               static_cast<uint32_t>(cart_naos),
                               d_Q_K_ss,
                               d_D_inds_K_ss,
                               d_pair_displs_K_ss,
                               d_pair_counts_K_ss,
                               d_pair_data_K_ss,
                               d_prim_cart_ao_to_atom_inds,
                               static_cast<uint32_t>(natoms),
                               d_atom_ids_l,
                               d_atom_ids_l_displs,
                               d_atom_ids_l_counts,
                               d_boys_func_table,
                               d_boys_func_ft,
                               omega,
                               eri_threshold);
            gpu::computeExchangeHessianSSSS_JK_0<<<num_blocks, threads_per_block, 0, stream>>>(
                               d_hess_array[grad_cart_ind],
                               d_hess_array[grad_cart_ind_T],
                               static_cast<uint32_t>(grad_cart_ind_0),
                               static_cast<uint32_t>(grad_cart_ind_1),
                               frac_exact_exchange,
                               d_pair_inds_i_for_K_ss,
                               d_pair_inds_k_for_K_ss,
                               d_D_ik_for_K_ss,
