                               d_D_inds_K_ss,
                               d_pair_displs_K_ss,
                               d_pair_counts_K_ss,
                               d_pair_data_K_ss,
                               d_prim_cart_ao_to_atom_inds,
                               static_cast<uint32_t>(natoms),
                               d_atom_ids_j,
                               d_atom_ids_j_displs,
                               d_atom_ids_j_counts,
                               d_boys_func_table,
                               d_boys_func_ft,
                               omega,
                               eri_threshold);
        }

        /*
        // K: (SS|SP)
        //     *  *

        for (int64_t grad_cart_ind = 0; grad_cart_ind < 3; grad_cart_ind++)
        {
            gpu::computeExchangeGradientSSSP_I_0<<<num_blocks, threads_per_block, 0, stream>>>(
                               d_hess_array[grad_cart_ind],
                               static_cast<uint32_t>(grad_cart_ind),
                               frac_exact_exchange,
                               d_pair_inds_i_for_K_ss,
                               d_pair_inds_k_for_K_ss,
                               d_D_ik_for_K_ss,
                               static_cast<uint32_t>(pair_inds_count_for_K_ss),
                               d_s_prim_info,
                               d_s_prim_aoinds,
                               static_cast<uint32_t>(s_prim_count),
                               d_p_prim_info,
                               d_p_prim_aoinds,
                               static_cast<uint32_t>(p_prim_count),
                               sp_max_D,
                               d_mat_D_full_AO,
                               static_cast<uint32_t>(cart_naos),
                               d_Q_K_ss,
                               d_Q_K_sp,
                               d_D_inds_K_ss,
                               d_D_inds_K_sp,
                               d_pair_displs_K_ss,
                               d_pair_displs_K_sp,
                               d_pair_counts_K_ss,
                               d_pair_counts_K_sp,
                               d_pair_data_K_ss,
                               d_pair_data_K_sp,
                               d_prim_cart_ao_to_atom_inds,
                               d_boys_func_table,
                               d_boys_func_ft,
                               omega,
                               eri_threshold);
            gpu::computeExchangeGradientSSSP_K_0<<<num_blocks, threads_per_block, 0, stream>>>(
                               d_hess_array[grad_cart_ind],
                               static_cast<uint32_t>(grad_cart_ind),
                               frac_exact_exchange,
                               d_pair_inds_i_for_K_ss,
                               d_pair_inds_k_for_K_ss,
                               d_D_ik_for_K_ss,
                               static_cast<uint32_t>(pair_inds_count_for_K_ss),
                               d_s_prim_info,
                               d_s_prim_aoinds,
                               static_cast<uint32_t>(s_prim_count),
                               d_p_prim_info,
                               d_p_prim_aoinds,
                               static_cast<uint32_t>(p_prim_count),
                               sp_max_D,
                               d_mat_D_full_AO,
                               static_cast<uint32_t>(cart_naos),
                               d_Q_K_ss,
                               d_Q_K_sp,
                               d_D_inds_K_ss,
                               d_D_inds_K_sp,
                               d_pair_displs_K_ss,
                               d_pair_displs_K_sp,
                               d_pair_counts_K_ss,
                               d_pair_counts_K_sp,
                               d_pair_data_K_ss,
                               d_pair_data_K_sp,
                               d_prim_cart_ao_to_atom_inds,
                               d_boys_func_table,
                               d_boys_func_ft,
                               omega,
                               eri_threshold);
        }

        // K: (SS|SD)
        //     *  *

